const body = $json.input?.body || $json.body || $json;
const clean = (v) => String(v ?? '').trim();
const name = clean(body.name || body.lead_name || body.clientName);
const contact = clean(body.contact || body.phone || body.email || body.lead_contact);
const service = clean(body.service || 'Консультація / масаж');
const note = clean(body.note || body.comment || body.message);
const CHANNELS=['WhatsApp','Viber','Telegram','Дзвінок','Email'];
let channel = clean(body.channel || body.preferred_channel || '');
if(!CHANNELS.includes(channel)) channel='Дзвінок';
const prefersCall = channel==='Дзвінок';
const createdAt = body.createdAt || new Date().toISOString();
const text = [name, contact, service, note, channel].join('\n');
const emergencyWords = ['температура','гострий біль','травма','операція','вагіт','онко','тромбоз','варикоз','запалення','серце'];
const flags = emergencyWords.filter(w => text.toLowerCase().includes(w));
return [{ json: { event:'intake', name, contact, service, note, channel, prefersCall, contactable_by_text: !prefersCall, createdAt, source: body.source || 'health-hand-site', riskFlags: flags, raw: body } }];

const body = $json.input?.body || $json.body || $json;
const clean = (v) => String(v ?? '').trim();
const CHANNELS=['WhatsApp','Viber','Telegram','Дзвінок','Email'];
let _ch = clean(body.channel || body.preferred_channel || '');
if(!CHANNELS.includes(_ch)) _ch='Дзвінок';
return [{ json: {
  event:'followup',
  name: clean(body.name || body.client_name),
  contact: clean(body.contact || body.phone || body.email),
  service: clean(body.service || 'масаж'),
  visit_status: clean(body.visit_status || body.status || 'completed'),
  last_note: clean(body.last_note || body.note || body.reply || ''),
  days_since_visit: Number(body.days_since_visit || 0),
  rating: body.rating ? Number(body.rating) : null,
  channel: _ch,
  prefersCall: _ch==='Дзвінок',
  contactable_by_text: _ch!=='Дзвінок',
  google_review_url: clean(body.google_review_url || 'https://maps.google.com/?q=Health+Hand+Uman')
}}];

const data = $json;
let content = data?.output || data?.choices?.[0]?.message?.content || '';
let ai = {};
try { ai = JSON.parse(content.replace(/^```json\s*/,'').replace(/```$/,'')); } catch(e) { ai = { summary_uk: content || 'AI summary unavailable', urgency_score: 2, contraindications: [], recommended_service: 'Консультація', admin_next_step: 'Зв’язатися з клієнтом', client_reply_uk: 'Дякуємо за заявку! Ми з вами зв’яжемося.' }; }
const lead = $('Normalize Intake').first().json;
const admin = `🖐 Health Hand: нова заявка
Клієнт: ${lead.name}
Контакт: ${lead.contact}
Канал: ${lead.channel}${lead.prefersCall ? ' (передзвонити)' : ''}
Послуга: ${lead.service}
Терміновість: ${ai.urgency_score}/5
AI: ${ai.summary_uk}
Крок: ${ai.admin_next_step}`;
return [{ json: { ok:true, event:'health_hand_ai_triage', lead, ai, admin_message: admin, client_message: ai.client_reply_uk } }];

const data = $json;
let content = data?.output || data?.choices?.[0]?.message?.content || '';
let ai = {};
try { ai = JSON.parse(content.replace(/^```json\s*/,'').replace(/```$/,'')); } catch(e) { ai = { sentiment:'neutral', action:'reengage', message_uk:'Доброго дня! Як самопочуття після масажу?', admin_note_uk:content }; }
const client = $('Normalize Followup').first().json;
if (ai.action === 'review_request' && client.google_review_url && !ai.message_uk.includes('http')) ai.message_uk += `

Будемо вдячні за відгук: ${client.google_review_url}`;
return [{ json: { ok:true, event:'health_hand_followup_review', client, ai } }];

const r = $json;
const due = Array.isArray(r) ? r : (r.due || r.data || r.body?.due || []);
const TPL = {
  before24h: (n,s) => (n ? n+', ' : '') + 'нагадуємо: завтра ваш запис у Health Hand (' + s + '). Якщо потрібно перенести час — напишіть нам заздалегідь.',
  before2h:  (n,s) => (n ? n+', ' : '') + 'сьогодні ваш сеанс у Health Hand (' + s + '). Будь ласка, приходьте на 5-10 хв раніше.'
};
const out = due.map(x => {
  const type = x.type || 'before24h';
  const msg = (TPL[type] || TPL.before24h)(x.name || '', x.service || 'масаж');
  const ch = x.channel || '';
  let deliver = 'manual';                 // WhatsApp / Viber / Telegram без chat_id
  if (ch === 'Email') deliver = 'email';  // авто-відправка можлива зараз
  else if (ch === 'Дзвінок' || x.prefers_call) deliver = 'call';
  return { json: { name:x.name||'', contact:x.contact||'', channel:ch,
    service:x.service||'', date:x.date||'', time:x.time||'',
    type, message: msg, deliver } };
});
return out.length ? out : [{ json: { deliver:'none', message:'Немає записів на завтра.' } }];

const src = $json.input?.body || $json.body || $json.input || $json;
const clean = (v) => String(v ?? '').trim();
const nested = src.message || src.messages?.[0] || src.entry?.[0]?.changes?.[0]?.value?.messages?.[0] || {};
const contactObj = src.contact || src.contacts?.[0] || src.entry?.[0]?.changes?.[0]?.value?.contacts?.[0] || {};
const text = clean(src.text || src.messageText || src.body || nested.text?.body || nested.body || nested.message || src.query);
const from = clean(src.from || src.phone || src.contact || nested.from || contactObj.wa_id || contactObj.phone || src.sender);
const name = clean(src.name || src.clientName || src.profileName || contactObj.profile?.name || contactObj.name);
return [{ json: {
  event: 'whatsapp',
  channel: 'WhatsApp',
  provider: clean(src.provider || 'whatsapp-provider'),
  message_text: text,
  name,
  contact: from,
  received_at: src.timestamp || new Date().toISOString(),
  raw: src
}}];

const source = $('Normalize WhatsApp Message').first().json;
const data = $json;
let content = data?.output || data?.choices?.[0]?.message?.content || '';
let ai = {};
try { ai = JSON.parse(content.replace(/^```json\s*/,'').replace(/```$/,'')); }
catch(e) { ai = { intent:'other', should_create_booking:false, missing_fields:['message'], client_reply_uk:'Дякуємо за повідомлення. Напишіть, будь ласка, яку послугу та зручний час ви хочете.', admin_note_uk: content || 'AI parse failed' }; }
const clean = (v) => String(v ?? '').trim();
const name = clean(ai.name || source.name);
const contact = clean(ai.contact || source.contact);
const service = clean(ai.service || '');
const shouldBook = Boolean(ai.should_create_booking && name.length >= 2 && contact.length >= 5 && service.length > 0);
const booking = {
  name, contact, service: service || 'Консультація / масаж',
  date: clean(ai.date), time: clean(ai.time),
  note: clean(ai.note || source.message_text),
  channel: 'WhatsApp', source: 'whatsapp-ai', webhookOk: true
};
return [{ json: { event:'health_hand_whatsapp_ai', source, ai, shouldBook, booking } }];

const prep = $('Prepare WhatsApp Booking').first().json;
const backend = $json?.booking_id || $json?.ok !== undefined ? $json : null;
const ai = prep.ai || {};
const booking = prep.booking || {};
const created = Boolean(backend?.ok && backend?.booking_id);
let client = ai.client_reply_uk || 'Дякуємо! Напишіть, будь ласка, яку послугу та зручний час ви хочете.';
if (created) client = client || 'Дякуємо, заявку прийнято. Ми підтвердимо час найближчим повідомленням.';
if (!created && prep.shouldBook) client = 'Дякуємо, бачу ваш запит. Я передам адміністратору, щоб підтвердити запис.';
const admin = `💬 Health Hand WhatsApp AI

Intent: ${ai.intent || '-'}
Booking created: ${created ? 'YES #' + backend.booking_id : 'NO'}
Клієнт: ${booking.name || prep.source?.name || '-'}
Контакт: ${booking.contact || prep.source?.contact || '-'}
Послуга: ${booking.service || '-'}
Дата/час: ${(booking.date || '-') + ' ' + (booking.time || '')}
Повідомлення: ${prep.source?.message_text || '-'}

AI: ${ai.admin_note_uk || ai.client_reply_uk || '-'}`;
return [{ json: { ok:true, event:'health_hand_whatsapp_ai', created_booking: created, booking_id: backend?.booking_id || null, client_message: client, whatsapp_reply: client, admin_message: admin, ai, booking, backend } }];

const body = $json.body || $json;
const message = String(body.message || '').trim().slice(0, 800);
const lower = message.toLowerCase();
const offtopicReply = 'Я консультант Health Hand і можу допомогти тільки з масажем, самопочуттям перед процедурою або записом. Напишіть, що турбує — шия, спина, плечі, обличчя — і я підкажу послугу.';
const complaintReply = 'Дякуємо за звернення. Опишіть, будь ласка, конкретну ситуацію у формі заявки на сайті й оберіть зручний канал зв’язку: Telegram, дзвінок або email. Адміністратор Health Hand зв’яжеться з вами.';
if (!message) return [{ json: { scope: 'offtopic', reply: offtopicReply, userMessage: '' } }];

const greetings = /^(привіт|добрий день|доброго дня|вітаю|hello|hi|доброго вечора|добрий вечір)[!.,\s]*$/i;
const complaint = /(скарг|скарж|незадовол|поган|жахлив|претензі|complaint|claim)/i;
const allowed = /(health\s*hand|хелс\s*хенд|салон|масаж|массаж|масажист|майстр|процедур|послуг|спин|шия|шиї|плеч|поперек|попереку|облич|щелеп|лімф|лімфодренаж|біль|болить|напруга|м'яз|мяз|суглоб|травм|онім|вагіт|протипоказ|запис|записат|бронь|резервац|візит|ціна|вартість|скільки коштує|прайс|час|графік|адрес|контакт|телефон|telegram|телеграм|дзвін|email|сертифікат|курс|догляд|після масаж|до масаж|адміністратор|хто у вас працює|хто працює|команд|працівник|персонал|спеціаліст)/i;
const blocked = /(скільки\s+\d|\d+\s*[+\-*/÷xх]\s*\d+|математ|алгебр|код|програм|javascript|python|напиши\s+(текст|лист|код|вірш|пісн)|переклади|реферат|домашн|задач|хто\s+такий|що\s+таке\s+(?!масаж|health hand|салон)|ігноруй|ignore|prompt|system prompt|інструкц)/i;

if (complaint.test(lower)) return [{ json: { scope: 'offtopic', reply: complaintReply, userMessage: message, page: body.page || '', channel: 'site-chat' } }];
let scope = 'offtopic';
if (greetings.test(lower) || allowed.test(lower)) scope = 'health_hand';
if (blocked.test(lower) && !allowed.test(lower)) scope = 'offtopic';

return [{ json: { scope, reply: offtopicReply, userMessage: message, page: body.page || '', channel: 'site-chat' } }];

let content = $json?.output || $json?.choices?.[0]?.message?.content || '';
let reply = '';
try { const parsed = JSON.parse(String(content).replace(/^```json\s*/, '').replace(/```$/, '')); reply = parsed.reply || parsed.message || ''; } catch (e) { reply = String(content || '').replace(/^```json\s*/, '').replace(/```$/, '').trim(); }
if (!reply) reply = 'Дякую за питання. Для точного запису напишіть нам у Telegram або залиште заявку на сайті.';
return [{ json: { ok: true, reply } }];

const employeePayload = items[0]?.json || {};
const servicePayload = $("Fetch Live Services").first().json || {};
const normalized = $("Normalize Chat Message").first().json || {};
const message = String(normalized.userMessage || '').trim();
const lower = message.toLowerCase();
const services = Array.isArray(servicePayload.services) ? servicePayload.services : [];
const employees = Array.isArray(employeePayload.employees) ? employeePayload.employees : [];
const money = (v) => `${Number(v)} грн`;
const minutes = (v) => `${Number(v)} хв`;
let direct = false;
let reply = '';

const asksServiceList = /(які.{0,30}послуг|переліч.{0,30}послуг|список.{0,20}послуг|усі.{0,20}послуг|актуальні.{0,20}послуг)/i.test(message);
const asksEmployees = /(хто.{0,20}працює|команд|працівник|персонал|спеціаліст)/i.test(message);
const asksPriceOrDuration = /(цін|варт|кошту|скільки|тривал|хвилин|час)/i.test(message);

if (asksServiceList) {
  direct = true;
  reply = services.length
    ? 'Актуальні послуги Health Hand:\n' + services.map(s => `• ${s.name} — ${money(s.price)}, ${minutes(s.duration_minutes)}. ${s.description || ''}`.trim()).join('\n')
    : 'Не вдалося отримати актуальний каталог. Залиште заявку у формі на сайті, і адміністратор уточнить послуги та ціни.';
} else if (asksEmployees) {
  direct = true;
  reply = employees.length
    ? 'У Health Hand працюють:\n' + employees.map(e => `• ${e.name}${e.bio ? ` — ${e.bio}` : ''}`).join('\n')
    : 'Не вдалося отримати актуальний список спеціалістів. Залиште заявку у формі на сайті, і адміністратор уточнить інформацію.';
} else if (asksPriceOrDuration) {
  const exact = [...services].sort((a,b) => String(b.name || '').length - String(a.name || '').length).find(s => lower.includes(String(s.name || '').toLowerCase()));
  if (exact) {
    direct = true;
    reply = `${exact.name}: ${money(exact.price)}, тривалість ${minutes(exact.duration_minutes)}.${exact.description ? ` ${exact.description}` : ''}`;
  }
}
return [{json:{...employeePayload,direct,reply,userMessage:message}}];

const input = items[0].json || {};
const body = input.body || input;
const eventId = String(body.event_id || '').trim();
const eventName = String(body.event_name || body.event || '').trim();
const headerEventId = String((input.headers || {})['x-event-id'] || '').trim();
if (!eventId || !eventName || headerEventId !== eventId) throw new Error('invalid automation event contract');
const now = Date.now();
const state = $getWorkflowStaticData('global');
state.backendEventIds = state.backendEventIds || {};
for (const [id, ts] of Object.entries(state.backendEventIds)) if (now - Number(ts) > 604800000) delete state.backendEventIds[id];
const duplicate = Boolean(state.backendEventIds[eventId]);
const labels = {automation_test:'Перевірка автоматизації',service_created:'Створено послугу',service_updated:'Оновлено послугу',service_disabled:'Приховано послугу',employee_created:'Додано працівника',employee_updated:'Оновлено працівника',employee_disabled:'Приховано працівника',shift_created:'Додано графік',shift_updated:'Оновлено графік',shift_deleted:'Видалено графік',booking_created:'Нова заявка',booking_status_changed:'Змінено статус запису',booking_deleted:'Видалено запис',user_registered:'Новий клієнт',customer_confirmation_requested:'Підтвердження клієнту'};
const sourcePayload = body.payload || body.data;
const payload = (sourcePayload && typeof sourcePayload === 'object') ? sourcePayload : {};
const clean = (v, fallback='—') => String(v ?? '').trim() || fallback;
const channelAction = payload.channel === 'Email' ? 'Email-підтвердження клієнту ставиться в окрему чергу.' : payload.channel === 'Telegram' ? 'Напишіть клієнту в Telegram за вказаним контактом.' : payload.channel === 'Дзвінок' ? 'Зателефонуйте клієнту для підтвердження.' : 'Уточніть зручний спосіб зв’язку.';
const adminMessage = eventName === 'booking_created'
  ? ['🆕 НОВА ЗАЯВКА HEALTH HAND', `Заявка №${clean(payload.booking_id)}`, '', `👤 Клієнт: ${clean(payload.lead_name)}`, `📇 Контакт: ${clean(payload.lead_contact)}`, `💬 Канал: ${clean(payload.channel)}`, '', `💆 Послуга: ${clean(payload.service)}`, `📅 Дата: ${clean(payload.date)}`, `🕐 Час: ${clean(payload.time)}`, `🧑‍⚕️ Майстер: ${clean(payload.employee_name, 'не обрано')}`, '', `📝 Побажання: ${clean(payload.note, 'не вказано')}`, '', `➡️ ${channelAction}`].join('\n')
  : `⚙️ Health Hand — ${labels[eventName] || 'Подія'}${[payload.service,payload.name,payload.status].filter(Boolean).length ? '\n' + [payload.service,payload.name,payload.status].filter(Boolean).join(' • ') : ''}`;
return [{json:{accepted:true,duplicate,event_id:eventId,event_name:eventName,label:labels[eventName]||'Подія Health Hand',payload,admin_message:adminMessage,is_customer_email:eventName === 'customer_confirmation_requested' && payload.channel === 'Email'}}];

const original = $('Normalize Backend Event').first().json;
const state = $getWorkflowStaticData('global');
state.backendEventIds = state.backendEventIds || {};
state.backendEventIds[original.event_id] = Date.now();
return [{json: original}];

